def c_autoajuste_acotado_1_sesgo50_largo(P, ctx, mod):
    aj = float(ctx.get("ajuste") or 1.0)
    nuevo_aj = min(1.0, aj)
    ctx["ajuste"] = nuevo_aj
    ph = (mod.get("aciertos") or {}).get("por_horizonte") or {}
    pts = [(0, 0.0)] + sorted((int(h), float(v["sesgo_m"])) for h, v in ph.items() if (v.get("n") or 0) >= 30 and v.get("sesgo_m") is not None)
    if len(pts) < 3:
        return None
    def s(t):
        for (h0, v0), (h1, v1) in zip(pts, pts[1:]):
            if t <= h1:
                return v0 + (v1 - v0) * (t - h0) / (h1 - h0)
        return pts[-1][1]
    c = mod.get("curva_mazar") or {"a": 3.6595, "b": 0.12497}
    dvdz = c["a"] + c["b"] * max(0.0, float(ctx["cota"]) - 2115.0)
    k = dvdz / 0.0864
    corr = [0.0 if d < 1 else max(-80.0, min(80.0, -(s(d + 1) - s(d)) * k * 0.5)) for d in range(60)]
    base = list(ctx.get("memoria") or [])
    n = max(len(base), len(corr))
    out = [round((base[i] if i < len(base) else 0.0) + (corr[i] if i < len(corr) else 0.0), 2) for i in range(n)]
    ctx["memoria"] = out
    return P, ctx, {"ajuste": nuevo_aj, "memoria": out}

